import { http } from './http'
import type { SafeUser } from './auth.types'

export const ROLE_NAMES = [
  'Department Head',
  'Event Coordinator',
  'Instructor',
  'Student Officer',
  'Student',
] as const

export async function listUsers(): Promise<SafeUser[]> {
  const { data } = await http.get<SafeUser[]>('/users')
  return data
}

export async function tryListUsers(): Promise<SafeUser[] | null> {
  try {
    return await listUsers()
  } catch {
    return null
  }
}

export async function assignRole(userId: string, role: string): Promise<SafeUser> {
  const { data } = await http.post<SafeUser>(`/users/${userId}/roles`, { role })
  return data
}

export async function removeRole(userId: string, roleName: string): Promise<SafeUser> {
  const { data } = await http.delete<SafeUser>(
    `/users/${userId}/roles/by-name/${encodeURIComponent(roleName)}`,
  )
  return data
}

export interface CreateUserPayload {
  email: string
  password: string
  firstName: string
  middleName?: string
  lastName: string
  suffix?: string
  isActive: boolean
  roles: string[]
  studentId?: string
  program?: string
  yearLevel?: number
}

export async function createUser(payload: CreateUserPayload): Promise<SafeUser> {
  const { data } = await http.post<SafeUser>('/users', payload)
  return data
}
import { http } from './http'

export const NOTIFICATION_TYPES = [
  'EventSubmitted',
  'EventApproved',
  'EventRejected',
  'RevisionRequested',
  'TaskAssigned',
] as const

export type NotificationType = (typeof NOTIFICATION_TYPES)[number]

export interface NotificationRecord {
  id: string
  userId: string
  eventId: string | null
  type: NotificationType
  message: string
  isRead: boolean
  createdAt: string
  updatedAt: string
}

export function countUnread(notifications: NotificationRecord[]): number {
  return notifications.filter((n) => !n.isRead).length
}

export async function listNotifications(): Promise<NotificationRecord[]> {
  const { data } = await http.get<NotificationRecord[]>('/notifications')
  return data
}

export async function markNotificationRead(
  id: string,
): Promise<NotificationRecord> {
  const { data } = await http.patch<NotificationRecord>(
    `/notifications/${id}/read`,
  )
  return data
}
import { http } from './http'

export const TASK_STATUSES = ['Todo', 'InProgress', 'Done'] as const
export type TaskStatus = (typeof TASK_STATUSES)[number]

export interface TaskUserRef {
  id: string
  firstName: string
  lastName: string
  email: string
}

export interface TaskRecord {
  id: string
  eventId: string
  title: string
  description: string | null
  assignedToUserId: string | null
  deadline: string
  status: TaskStatus
  createdAt: string
  updatedAt: string
  assignedToUser: TaskUserRef | null
}

export interface CreateTaskInput {
  title: string
  description?: string
  assignedToUserId?: string | null
  deadline: string
}

export interface UpdateTaskInput {
  title?: string
  description?: string
  assignedToUserId?: string | null
  deadline?: string
  status?: TaskStatus
}

export function isTaskStatus(value: string): value is TaskStatus {
