    { id: `${e.id}-d1`, eventId: e.id, uploadedById: 'u-3', docType: 'Proposal', filePath: `/uploads/${e.id}/proposal.pdf`, originalFilename: 'Event_Proposal_v3.pdf`, '.replace('`, ', ''), mimeType: 'application/pdf', fileSize: 284310, createdAt: now(), updatedAt: now(), uploadedBy: pickUser('u-3') },
    { id: `${e.id}-d2`, eventId: e.id, uploadedById: 'u-5', docType: 'Program`, '.replace('`, ', ''), filePath: `/uploads/${e.id}/program.pdf`, originalFilename: 'Program_Flow.pdf', mimeType: 'application/pdf', fileSize: 122880, createdAt: now(), updatedAt: now(), uploadedBy: pickUser('u-5') },
    { id: `${e.id}-d3`, eventId: e.id, uploadedById: 'u-4', docType: 'Photo', filePath: `/uploads/${e.id}/photo1.jpg`, originalFilename: 'venue_ocular.jpg', mimeType: 'image/jpeg', fileSize: 1980224, createdAt: now(), updatedAt: now(), uploadedBy: pickUser('u-4') },
  ]

  APPROVALS[e.id] = [
    { id: `${e.id}-ap1`, eventId: e.id, reviewerId: null, action: 'Submitted', comments: 'Submitted for department review.', createdAt: now(), reviewer: null },
    ...(e.status !== 'PendingApproval' && e.status !== 'Draft'
      ? [{ id: `${e.id}-ap2`, eventId: e.id, reviewerId: 'u-2', action: e.status === 'Rejected' ? 'Rejected' : e.status === 'RevisionRequired' ? 'RevisionRequested' : 'Approved', comments: 'Reviewed against the activities calendar.', createdAt: now(), reviewer: pickUser('u-2') }]
      : []),
  ]
})

function pickUser(id) {
  const u = USERS.find((x) => x.id === id)
  return u ? { id: u.id, firstName: u.firstName, lastName: u.lastName, email: u.email } : null
}
function datePart(iso) {
  return iso.slice(0, 10)
}

const NOTIFICATIONS = [
  { id: 'n-1', userId: 'u-admin', eventId: 'e-3', type: 'EventSubmitted', message: 'Culinary Arts Inter-School Competition is awaiting your approval.', isRead: false, createdAt: now(), updatedAt: now() },
  { id: 'n-2', userId: 'u-admin', eventId: 'e-4', type: 'RevisionRequested', message: 'Revision requested on Heritage Food Trail: Old Town Edition.', isRead: false, createdAt: now(), updatedAt: now() },
  { id: 'n-3', userId: 'u-admin', eventId: 'e-1', type: 'EventApproved', message: 'Annual Hospitality Summit 2026 was approved.', isRead: true, createdAt: now(), updatedAt: now() },
  { id: 'n-4', userId: 'u-admin', eventId: null, type: 'TaskAssigned', message: 'You were assigned to a task in Barista Skills Workshop.', isRead: true, createdAt: now(), updatedAt: now() },
]

const AUDIT = Array.from({ length: 47 }, (_, i) => {
  const u = USERS[i % USERS.length]
  const methods = ['POST', 'GET', 'PATCH', 'PUT', 'DELETE']
  const paths = ['/events', '/events/e-1/approve', '/users/u-6/roles', '/auth/login', '/events/e-2/participants', '/audit', '/reports/summary']
  return {
    id: `log-${i}`,
    userId: u.id,
    user: { id: u.id, email: u.email, firstName: u.firstName, lastName: u.lastName },
    method: methods[i % methods.length],
    path: paths[i % paths.length],
    entity: ['Event', 'User', 'Attendance', 'Notification'][i % 4],
    action: ['Create', 'Update', 'Delete', 'Login', 'Approve'][i % 5],
    body: i % 3 === 0 ? { title: 'Annual Hospitality Summit 2026', status: 'Approved' } : { id: 'u-6', role: 'Student Officer' },
    statusCode: i % 11 === 0 ? 403 : i % 7 === 0 ? 409 : 200,
    createdAt: new Date(Date.now() - i * 3600_000 * 5).toISOString(),
  }
})

function safeUsers() {
  return USERS.map((u) => ({ ...u }))
}

function eventReport(event) {
  const parts = PARTICIPANTS[event.id]
  const att = ATTENDANCE[event.id]
  const rows = parts.map((p, i) => {
    const a = att[i]
    const name = p.user ? `${p.user.firstName} ${p.user.lastName}` : p.externalName
    return {
      participantId: p.id,
      name,
      participantType: p.participantType,
      email: p.user ? p.user.email : null,
      attendanceStatus: a ? a.status : null,
      timeIn: a ? a.timeIn : null,
      timeOut: a ? a.timeOut : null,
      isAbsentee: a ? a.status === 'Absent' : false,
      absenteeReason: a && a.status === 'Absent' ? 'Did not sign in during the capture window' : null,
    }
  })
  const present = rows.filter((r) => r.attendanceStatus === 'Present').length
  const absent = rows.filter((r) => r.attendanceStatus === 'Absent').length
  const total = rows.length
  return {
    event: {
      id: event.id,
      title: event.title,
      status: event.status,
      eventDate: event.eventDate,
      venue: event.venue,
      eventType: event.eventType ? event.eventType.name : null,
      description: event.description,
    },
    participantTypes: groupCount(rows, 'participantType'),
    stats: {
      registered: total,
      present,
      absent,
      missing: 0,
      absentees: absent,
      presentRate: pct(present, total),
      absentRate: pct(absent, total),
    },
    participants: rows,
    absentees: rows.filter((r) => r.isAbsentee),
    tasks: { total: TASKS[event.id].length, done: TASKS[event.id].filter((t) => t.status === 'Done').length, completionRate: pct(TASKS[event.id].filter((t) => t.status === 'Done').length, TASKS[event.id].length) },
    absenteeDefinition: 'A registered participant without a recorded time-in for the event.',
  }
}

function groupCount(rows, key) {
  const m = new Map()
  rows.forEach((r) => m.set(r[key], (m.get(r[key]) ?? 0) + 1))
  return [...m.entries()].map(([k, count]) => ({ type: k, count }))
}
function pct(a, b) {
  return b ? Math.round((a / b) * 1000) / 10 : 0
}

function summaryReport() {
  const byStatus = groupCount(EVENTS, 'status')
  const rows = EVENTS.map((e) => {
    const parts = PARTICIPANTS[e.id]
    const att = ATTENDANCE[e.id]
    const present = att.filter((a) => a.status === 'Present').length
    const absent = att.filter((a) => a.status === 'Absent').length
    return {
      eventId: e.id,
      title: e.title,
      status: e.status,
      registered: parts.length,
      present,
      absent,
      missing: 0,
      presentRate: pct(present, parts.length),
      absentRate: pct(absent, parts.length),
    }
  })
  const totalAtt = rows.reduce((s, r) => s + r.present + r.absent, 0)
  const totalPresent = rows.reduce((s, r) => s + r.present, 0)
  const totalTasks = EVENTS.reduce((s, e) => s + TASKS[e.id].length, 0)
  const doneTasks = EVENTS.reduce((s, e) => s + TASKS[e.id].filter((t) => t.status === 'Done').length, 0)
  return {
    events: {
      total: EVENTS.length,
      completed: EVENTS.filter((e) => e.status === 'Completed').length,
      byStatus,
      byType: TYPES.map((t) => ({ type: t.name, count: EVENTS.filter((e) => e.eventTypeId === t.id).length })),
    },
    participants: {
      total: EVENTS.reduce((s, e) => s + PARTICIPANTS[e.id].length, 0),
      byType: [
        { type: 'Student', count: 96 },
        { type: 'Staff', count: 18 },
        { type: 'Guest', count: 12 },
      ],
    },
    attendance: {
      present: totalPresent,
      absent: totalAtt - totalPresent,
      recorded: totalAtt,
      presentRate: pct(totalPresent, totalAtt),
      absentRate: pct(totalAtt - totalPresent, totalAtt),
      byEvent: rows,
    },
    tasks: { total: totalTasks, done: doneTasks, completionRate: pct(doneTasks, totalTasks) },
    absenteeDefinition: 'A registered participant without a recorded time-in for the event.',
  }
}

// --- routing -------------------------------------------------------------

function match(method, path) {
  const p = path.split('?')[0]
  const seg = p.split('/').filter(Boolean)

  if (method === 'POST' && p === '/auth/login') return login()
  if (method === 'POST' && p === '/auth/refresh') return ok(ADMIN ? { accessToken: token(), refreshToken: 'r', user: current.user } : {})
  if (method === 'POST' && p === '/auth/logout') return ok({})

  if (method === 'GET' && p === '/auth/me') return ok(current.user)
  if (method === 'POST' && p === '/auth/change-password') return ok({ ...current.user, mustChangePassword: false })

  if (method === 'GET' && p === '/users') return ok(safeUsers())
  if (method === 'POST' && p === '/users') return ok({ ...ADMIN, id: 'u-new' })
  if (method === 'POST' && /^\/users\/[^/]+\/roles$/.test(p)) return ok(safeUsers()[4])
  if (method === 'DELETE' && /^\/users\/[^/]+\/roles\/by-name\/[^/]+$/.test(p)) return ok(safeUsers()[4])

  if (method === 'GET' && (p === '/events' || p === '/public/events')) {
    const q = new URLSearchParams(path.split('?')[1] ?? '')
    let items = EVENTS.slice()
    const status = q.get('status')
    if (status) items = items.filter((e) => e.status === status)
    const type = q.get('type')
    if (type) items = items.filter((e) => e.eventTypeId === type)
    const scope = q.get('campusScope')
    if (scope) items = items.filter((e) => e.campusScope === scope)
    const offset = Number(q.get('offset') ?? 0)
    const limit = Number(q.get('limit') ?? items.length)
    return ok({ items: items.slice(offset, offset + limit), total: items.length })
  }

  if (method === 'GET' && /^\/(public\/)?events\/[^/]+$/.test(p)) {
    const id = seg[seg.length - 1]
    const e = EVENTS.find((x) => x.id === id)
    return e ? ok(e) : notFound()
  }

  if (method === 'GET' && p === '/approvals/pending') {
    const items = EVENTS.filter((e) => e.status === 'PendingApproval' || e.status === 'RevisionRequired').map((e) => ({ ...e, approvals: APPROVALS[e.id] }))
    return ok({ items, total: items.length })
  }

  if (method === 'GET' && /^\/events\/[^/]+\/approval-history$/.test(p)) {
    return ok(APPROVALS[seg[1]] ?? [])
  }

  if (method === 'GET' && /^\/events\/[^/]+\/participants$/.test(p)) return ok(PARTICIPANTS[seg[1]] ?? [])
  if (method === 'GET' && /^\/events\/[^/]+\/attendance$/.test(p)) return ok(ATTENDANCE[seg[1]] ?? [])
  if (method === 'GET' && /^\/events\/[^/]+\/tasks$/.test(p)) return ok(TASKS[seg[1]] ?? [])
  if (method === 'GET' && /^\/events\/[^/]+\/schedule$/.test(p)) return ok(SCHEDULE[seg[1]] ?? [])
  if (method === 'GET' && /^\/events\/[^/]+\/committees$/.test(p)) return ok(COMMITTEES[seg[1]] ?? [])
  if (method === 'GET' && /^\/events\/[^/]+\/documents$/.test(p)) return ok(DOCUMENTS[seg[1]] ?? [])

  if (method === 'GET' && p === '/attendance/me') {
    const rows = []
    const mine = [EVENTS[0], EVENTS[5], EVENTS[6], EVENTS[1]]
    mine.forEach((e, i) => {
      const att = ATTENDANCE[e.id][i % ATTENDANCE[e.id].length]
      rows.push({ event: e, attendance: att })
    })
    return ok(rows)
  }

  if (method === 'GET' && p === '/notifications') return ok(NOTIFICATIONS)
  if (method === 'PATCH' && /^\/notifications\/[^/]+\/read$/.test(p)) {
    const n = NOTIFICATIONS.find((x) => x.id === seg[1])
    if (n) { n.isRead = true; n.updatedAt = now() }
    return ok(n ?? NOTIFICATIONS[0])
  }

  if (method === 'GET' && p === '/audit') {
    const q = new URLSearchParams(path.split('?')[1] ?? '')
    const page = Number(q.get('page') ?? 1)
    const pageSize = Number(q.get('pageSize') ?? 20)
    return ok({ items: AUDIT.slice((page - 1) * pageSize, page * pageSize), total: AUDIT.length, page, pageSize })
  }

  if (method === 'GET' && p === '/reports/summary') return ok(summaryReport())
  if (method === 'GET' && /^\/reports\/events\/[^/]+\/summary$/.test(p)) {
    const e = EVENTS.find((x) => x.id === seg[2])
    return e ? ok(eventReport(e)) : notFound()
  }
  if (method === 'GET' && /^\/reports\/events\/[^/]+\/(attendance|participants)\.csv$/.test(p)) {
    const name = p.endsWith('attendance.csv') ? 'attendance.csv' : 'participants.csv'
    return {
      status: 200,
      headers: { 'content-type': 'text/csv', 'content-disposition': `attachment; filename="${name}"` },
      body: 'name,type,status,time-in,time-out\nAngela Aguilar,Student,Present,08:02,17:10\n',
    }
  }
  if (method === 'GET' && /^\/reports\/events\/[^/]+\/report\.pdf$/.test(p)) {
    return { status: 200, headers: { 'content-type': 'application/pdf', 'content-disposition': 'attachment; filename="report.pdf"' }, body: Buffer.from('%PDF-1.4 mock') }
  }

  if (method === 'POST' && /^\/events$/.test(p)) return ok({ ...EVENTS[4], conflictWarning: null })
  if (method === 'PUT' && /^\/events\/[^/]+$/.test(p)) return ok({ ...EVENTS[0], conflictWarning: null })
  if (method === 'POST' && /^\/events\/[^/]+\/(submit|approve|reject|request-revision)$/.test(p)) {
    const e = EVENTS.find((x) => x.id === seg[1])
    if (!e) return notFound()
    if (seg[2] === 'approve') return ok({ ...e, status: 'Approved', conflictWarning: null })
    if (seg[2] === 'submit') return ok({ ...e, status: 'PendingApproval' })
    if (seg[2] === 'reject') return ok({ ...e, status: 'Rejected' })
    return ok({ ...e, status: 'RevisionRequired' })
  }
  if (method === 'POST' && /^\/events\/[^/]+\/(participants|tasks|schedule|committees|documents)$/.test(p)) {
    const id = seg[1]
    const kind = seg[2]
    const base = (kind === 'participants' ? PARTICIPANTS : kind === 'tasks' ? TASKS : kind === 'schedule' ? SCHEDULE : kind === 'committees' ? COMMITTEES : DOCUMENTS)[id]
    const created = base ? base[0] : null
    return created ? ok(created) : notFound()
  }
  if (method === 'PATCH' && /^\/events\/[^/]+\/(tasks|schedule)\/[^/]+$/.test(p)) {
    const list = (seg[2] === 'tasks' ? TASKS : SCHEDULE)[seg[1]]
    return list && list[0] ? ok(list[0]) : notFound()
  }
  if (method === 'POST' && /^\/events\/[^/]+\/attendance\/time-(in|out)$/.test(p)) {
    const list = ATTENDANCE[seg[1]]
    return list && list[0] ? ok(list[0]) : notFound()
  }
  if (method === 'POST' && p === '/attendance/sync') return ok({ accepted: [], rejected: [] })
  if (method === 'POST' && p === '/users/u-x') return ok(USERS[1])

  return notFound()
}

let current = { user: ADMIN }
function token() {
  return 'mock-access-token'
}
function login() {
  return ok({ accessToken: token(), refreshToken: 'mock-refresh-token', user: current.user })
}
function ok(body) {
  return { status: 200, headers: { 'content-type': 'application/json' }, body: JSON.stringify(body) }
}
function notFound() {
  return { status: 404, headers: { 'content-type': 'application/json' }, body: JSON.stringify({ message: 'Not found (mock)' }) }
}

const server = http.createServer((req, res) => {
  const chunks = []
  req.on('data', (c) => chunks.push(c))
  req.on('end', () => {
    const raw = Buffer.concat(chunks).toString('utf8')
    // Pick the acting user from the login payload (or the bearer token id hint).
    if (req.url === '/auth/login' && raw) {
      try {
        const body = JSON.parse(raw)
        current = { user: String(body.email || '').toLowerCase().includes('student') ? STUDENT : ADMIN }
      } catch {
        /* keep default */
      }
    }

    const cors = {
      'access-control-allow-origin': req.headers.origin || 'http://localhost:5173',
      'access-control-allow-credentials': 'true',
      'access-control-allow-headers': 'content-type,authorization',
      'access-control-allow-methods': 'GET,POST,PUT,PATCH,DELETE,OPTIONS',
    }

    if (req.method === 'OPTIONS') {
      res.writeHead(204, cors)
      res.end()
      return
    }

    let out
    try {
      out = match(req.method, req.url)
    } catch (err) {
      out = { status: 500, headers: { 'content-type': 'application/json' }, body: JSON.stringify({ message: String(err) }) }
    }
    res.writeHead(out.status, { ...cors, ...out.headers })
    res.end(out.body ?? '')
    console.log(`${req.method} ${req.url} -> ${out.status}`)
  })
})

server.listen(PORT, () => console.log(`mock HEMS API listening on http://localhost:${PORT}`))

