(()=>{
const f=document.getElementById('frame');const doc=f.contentDocument;const w=f.contentWindow;
const targets={hamburger:'[data-testid="mobile-nav-toggle"]',bell:'[data-testid="notification-bell"]',theme:'[data-testid="theme-toggle"]'};
const res={};
for(const [k,sel] of Object.entries(targets)){
  const el=doc.querySelector(sel); if(!el){res[k]='missing';continue}
  const r=el.getBoundingClientRect();
  // sample a 44x44 box centred on the control; count points that hit the control or its descendants
  const cx=r.x+r.width/2, cy=r.y+r.height/2; let hit=0,miss=0,missEx=[];
  for(let dx=-22;dx<22;dx+=2)for(let dy=-22;dy<22;dy+=2){
    const t=doc.elementFromPoint(cx+dx,cy+dy);
    if(t&&(t===el||el.contains(t)))hit++;else{miss++;if(missEx.length<3)missEx.push(t?t.className.toString().slice(0,26):'null')}
  }
  res[k]={box:Math.round(r.width)+'x'+Math.round(r.height),hit44:hit,miss,missEx};
}
return res})()

