const f=document.getElementById('frame');const doc=f.contentDocument;const w=f.contentWindow;
const btn=doc.querySelector('[data-testid="mobile-nav-toggle"]');const nav=doc.querySelector('#app-main-nav');
const info={ariaControls:btn.getAttribute('aria-controls'),navId:nav&&nav.id,ariaExpandedOpen:btn.getAttribute('aria-expanded')};
btn.click(); await new Promise(r=>setTimeout(r,300));
info.open=doc.querySelector('.app-bar__nav').className.includes('--open');
info.expandedAfterOpen=btn.getAttribute('aria-expanded');
// Escape
doc.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true}));
await new Promise(r=>setTimeout(r,300));
info.closedByEsc=!doc.querySelector('.app-bar__nav').className.includes('--open');
info.focusAfterEsc=doc.activeElement===btn;
// outside click
btn.click(); await new Promise(r=>setTimeout(r,300));
info.reopened=doc.querySelector('.app-bar__nav').className.includes('--open');
const main=doc.querySelector('main')||doc.body;
main.dispatchEvent(new MouseEvent('click',{bubbles:true}));
await new Promise(r=>setTimeout(r,300));
info.closedByOutsideClick=!doc.querySelector('.app-bar__nav').className.includes('--open');
return info})()

