const w=document.getElementById('frame').contentWindow, d=w.document;
const bar=d.querySelector('.app-bar'); const B=bar.getBoundingClientRect();
const cs=w.getComputedStyle(bar);
const box=(sel)=>{const e=typeof sel==='string'?d.querySelector(sel):sel; if(!e)return null; const r=e.getBoundingClientRect();
  return {x:Math.round(r.x),y:Math.round(r.y),w:Math.round(r.width),h:Math.round(r.height),right:Math.round(r.right),bottom:Math.round(r.bottom)}};
const inside=(b)=>b? (b.x>=B.x-1 && b.right<=B.right+1 && b.y>=B.y-1 && b.bottom<=B.bottom+1) : null;
const left=box('.app-bar__left'), prof=box('.app-bar__profile');
const ham=box('[data-testid="mobile-nav-toggle"]'), brand=box('.app-bar__brand')||box('.app-bar__logo')||box('.app-bar__left img');
const bell=box('.notification-bell'), avatar=box('.app-bar__avatar'), user=box('.app-bar__user'), role=box('.app-bar__role'), theme=box('[data-testid="theme-toggle"]');
// content edges for alignment comparison
const card=d.querySelector('.ui-card')||d.querySelector('main section')||d.querySelector('main');
const C=card?card.getBoundingClientRect():null;
return {
  viewport:w.innerWidth, scrollWidth:d.documentElement.scrollWidth,
  bar:{x:Math.round(B.x),y:Math.round(B.y),w:Math.round(B.width),h:Math.round(B.height),pos:cs.position,pad:cs.padding,z:cs.zIndex},
  rows:{left,profile:prof,gap:prof&&left?Math.round(prof.y-left.bottom):null,overlap:prof&&left?(prof.y<left.bottom):null},
  row1:{ham,brand,insideRow1:[inside(ham),inside(brand)]},
  row2:{bell,avatar,user,role,theme,allInside:[inside(bell),inside(avatar),inside(user),inside(role),inside(theme)]},
  overflowers:[ham,brand,bell,avatar,user,role,theme].filter(b=>b&&(b.x<B.x-1||b.right>B.right+1)).map(b=>JSON.stringify(b)),
  alignment:{contentLeft:C?Math.round(C.x):null,contentRight:C?Math.round(C.right):null,hamLeft:ham?ham.x:null,themeRight:theme?theme.right:null},
  nameWrap:user&&role?{userH:user.h,roleH:role.h,stacked:role.y>=user.bottom-2}:null
}})()

