const tabID="tab_a8ffd00a-e153-4f51-836f-7c9a3f6a9b45";
const sleep=(ms)=>tools.browser.evaluate({tabID,script:`new Promise(r=>setTimeout(r,${ms})).then(()=>'s')`});
const probe=`(()=>{
 const w=document.getElementById('frame').contentWindow,d=w.document;
 const bar=d.querySelector('.app-bar'), B=bar.getBoundingClientRect(), cs=w.getComputedStyle(bar);
 const padL=parseFloat(cs.paddingLeft), padR=parseFloat(cs.paddingRight);
 const ham=d.querySelector('[data-testid="mobile-nav-toggle"]').getBoundingClientRect();
 const brand=(d.querySelector('.app-bar__brand')||d.querySelector('.app-bar__left img')).getBoundingClientRect();
 const prof=d.querySelector('.app-bar__profile').getBoundingClientRect();
 const twoRows = prof.y >= brand.bottom - 1;
 const tag=d.querySelector('.app-bar__tag');
 const tagW = tag && w.getComputedStyle(tag).display!=='none' ? Math.round(tag.getBoundingClientRect().width) : 0;
 const meta=d.querySelector('.app-bar__profile-meta');
 const metaW = meta && w.getComputedStyle(meta).display!=='none' ? Math.round(meta.getBoundingClientRect().width) : 0;
 const colGap=parseFloat(cs.columnGap)||0;
 // single-row requirement: left group + gap + profile
 const needed = (ham.width + colGap + brand.width) + colGap + prof.width;
 const available = B.width - padL - padR;
 return {vw:w.innerWidth, client:w.document.documentElement.clientWidth, h:Math.round(B.height),
   twoRows, pad:[cs.paddingLeft,cs.paddingRight],
   left:Math.round(ham.x), rightEdge:Math.round(B.right-padR),
   ham:Math.round(ham.width), brand:Math.round(brand.width), prof:Math.round(prof.width),
   metaW, tagW, needed:Math.round(needed), available:Math.round(available),
   slack:Math.round(available-needed), twoRowSlack:Math.round(available-(ham.width+colGap+brand.width)),
   contentGutter:(()=>{const c=d.querySelector('main .ui-card')||d.querySelector('.ui-card');return c?Math.round(c.getBoundingClientRect().x):null})()
 }})()`;
const out={};
for (const v of [320,360,390,414,430,480,520,600,767]) {
  await tools.browser.evaluate({tabID,script:`window.__set(${v},900); window.__nav('/dashboard'); 'ok'`});
  await sleep(1600);
  const r=await tools.browser.evaluate({tabID,script:probe});
  out[v]=r.value;
}
console.log(JSON.stringify(out,null,1));

