const tabID="tab_a8ffd00a-e153-4f51-836f-7c9a3f6a9b45";
const sleep=(ms)=>tools.browser.evaluate({tabID,script:`new Promise(r=>setTimeout(r,${ms})).then(()=>'s')`});
await tools.browser.reload({tabID});
await sleep(4500);
const probe=`(()=>{
 const w=document.getElementById('frame').contentWindow,d=w.document;
 const bar=d.querySelector('.app-bar'),B=bar.getBoundingClientRect(),cs=w.getComputedStyle(bar);
 const ham=d.querySelector('[data-testid="mobile-nav-toggle"]');
 const hamR=ham.getBoundingClientRect();
 const brand=(d.querySelector('.app-bar__brand')||d.querySelector('.app-bar__left img')).getBoundingClientRect();
 const prof=d.querySelector('.app-bar__profile').getBoundingClientRect();
 const meta=d.querySelector('.app-bar__profile-meta');
 const metaVis=meta?w.getComputedStyle(meta).display!=='none':false;
 const theme=d.querySelector('[data-testid="theme-toggle"]').getBoundingClientRect();
 const nav=d.querySelector('#app-main-nav');
 const navR=nav.getBoundingClientRect();
 const navCs=w.getComputedStyle(nav);
 const card=d.querySelector('main .ui-card')||d.querySelector('.ui-card');
 const cardR=card?card.getBoundingClientRect():null;
 const hamDisp=w.getComputedStyle(ham).display;
 return {
  vw:w.innerWidth, h:Math.round(B.height), twoRows:prof.y>=brand.bottom-1,
  padL:cs.paddingLeft, hamX:Math.round(hamR.x), themeRight:Math.round(theme.right),
  cardL:cardR?Math.round(cardR.x):null, cardR:cardR?Math.round(cardR.right):null,
  alignLeft:cardR?Math.round(hamR.x-cardR.x):null, alignRight:cardR?Math.round(theme.right-cardR.right):null,
  metaVis, hamVis:hamDisp!=='none',
  navH:Math.round(navR.height), navOverflow:nav.scrollWidth>nav.clientWidth+1,
  navScrollW:nav.scrollWidth, navW:Math.round(navR.clientWidth),
  scrollW:d.documentElement.scrollWidth, clientW:d.documentElement.clientWidth
 }})()`;
const out={};
for (const v of [320,360,390,414,430,520,640,767,768,900,1024,1100,1280]) {
  await tools.browser.evaluate({tabID,script:`window.__set(${v},900); window.__nav('/dashboard'); 'ok'`});
  await sleep(1500);
  const r=await tools.browser.evaluate({tabID,script:probe});
  out[v]=r.value;
}
console.log(JSON.stringify(out,null,1));

