const tabID="tab_a8ffd00a-e153-4f51-836f-7c9a3f6a9b45";
const sleep=(ms)=>tools.browser.evaluate({tabID,script:`new Promise(r=>setTimeout(r,${ms})).then(()=>'s')`});
const res={};
for (const v of [320,430,767]) {
  await tools.browser.evaluate({tabID,script:`window.__set(${v},844); window.__nav('/dashboard'); 'ok'`});
  await sleep(1800);
  const panel=await tools.browser.evaluate({tabID,script:`(async()=>{
   const w=document.getElementById('frame').contentWindow,d=w.document;
   const bellBtn=d.querySelector('[data-testid="notification-bell"]')||d.querySelector('.notification-bell button')||d.querySelector('.notification-bell');
   bellBtn.click();
   await new Promise(r=>setTimeout(r,450));
   const p=d.querySelector('.notification-bell__panel'); const r=p.getBoundingClientRect();
   const card=(d.querySelector('main .ui-card')||d.querySelector('.ui-card')).getBoundingClientRect();
   const open=!p.hasAttribute('hidden')&&w.getComputedStyle(p).display!=='none';
   // esc close
   d.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true}));
   await new Promise(r=>setTimeout(r,300));
   const closed=w.getComputedStyle(p).display==='none'||p.hasAttribute('hidden');
   return {open,panelX:Math.round(r.x),panelRight:Math.round(r.right),panelW:Math.round(r.width),
           cardL:Math.round(card.x),cardR:Math.round(card.right),
           onScreen:r.x>=0&&r.right<=w.innerWidth, alignedL:Math.round(r.x-card.x),alignedR:Math.round(r.right-card.right),escClosed:closed}})()`});
  const drawer=await tools.browser.evaluate({tabID,script:`(async()=>{
   const w=document.getElementById('frame').contentWindow,d=w.document;
   d.querySelector('[data-testid="mobile-nav-toggle"]').click();
   await new Promise(r=>setTimeout(r,450));
   const n=d.querySelector('#app-main-nav').getBoundingClientRect();
   const bar=d.querySelector('.app-bar').getBoundingClientRect();
   const items=[...d.querySelectorAll('#app-main-nav a,#app-main-nav button')].map(a=>Math.round(a.getBoundingClientRect().height));
   const focused=d.activeElement?d.activeElement.tagName+':'+(d.activeElement.textContent||'').trim().slice(0,14):null;
   d.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true}));
   await new Promise(r=>setTimeout(r,350));
   const navC=w.getComputedStyle(d.querySelector('#app-main-nav'));
   return {navX:Math.round(n.x),navW:Math.round(n.width),navTop:Math.round(n.y),barBottom:Math.round(bar.bottom),
           minItem:Math.min(...items),items:items.length,focused,escClosed:navC.display==='none'}})()`});
  res[v]={panel:panel.value,drawer:drawer.value};
}
console.log(JSON.stringify(res,null,1));

