 const w=document.getElementById('frame').contentWindow,d=w.document;
 const vis=(sel)=>{const p=d.querySelector(sel); if(!p) return 'gone';
   const cs=w.getComputedStyle(p); const b=p.getBoundingClientRect();
   return (cs.display==='none'||cs.visibility==='hidden'||b.width===0)?'hidden':'shown'};
