 btn.click(); await new Promise(r=>setTimeout(r,450));
 const opened=vis('.notification-bell__panel');
 d.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true,cancelable:true}));
 await new Promise(r=>setTimeout(r,450));
 const afterEsc=vis('.notification-bell__panel');
 // also test window-targeted escape in case listener is on window
 btn.click(); await new Promise(r=>setTimeout(r,400));
 w.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true,cancelable:true}));
 await new Promise(r=>setTimeout(r,400));
 const afterEscWin=vis('.notification-bell__panel');
 // outside click
 btn.click(); await new Promise(r=>setTimeout(r,400));
 d.body.dispatchEvent(new MouseEvent('click',{bubbles:true}));
 await new Promise(r=>setTimeout(r,400));
 const afterOutside=vis('.notification-bell__panel');
 return {opened,afterEsc,afterEscWin,afterOutside,triggerAria:btn.getAttribute('aria-expanded')||btn.getAttribute('aria-controls')||'(none)'}})()`});
