const tabID="tab_a8ffd00a-e153-4f51-836f-7c9a3f6a9b45";
const sleep=(ms)=>tools.browser.evaluate({tabID,script:`new Promise(r=>setTimeout(r,${ms})).then(()=>'s')`});
const routes=['/dashboard','/events','/events/new','/events/1','/events/1/edit','/participants','/tasks','/reports','/reports/1','/attendance/capture','/admin/users','/admin/audit','/change-password'];
const audit=`(()=>{const w=document.getElementById('frame').contentWindow,d=d0();
 function d0(){return document.getElementById('frame').contentDocument}
 const de=d.documentElement;
 const over=de.scrollWidth>de.clientWidth+1;
 // anything wider than the viewport?
 const bad=[...d.querySelectorAll('body *')].filter(el=>{const r=el.getBoundingClientRect();
   return r.width>0 && (r.right>w.innerWidth+1||r.left<-1)}).slice(0,4).map(el=>el.className&&el.className.baseVal===undefined?String(el.className).slice(0,40):el.tagName);
 return {scrollW:de.scrollWidth,clientW:de.clientWidth,over,bad}})()`;
const out={};
for (const v of [320,430,767,768,1024,1280]) {
  await tools.browser.evaluate({tabID,script:`window.__set(${v},844); 'ok'`});
  const issues=[];
  for (const r of routes) {
    await tools.browser.evaluate({tabID,script:`window.__nav('${r}'); 'ok'`});
    await sleep(900);
    const a=await tools.browser.evaluate({tabID,script:audit});
    if (a.value.over||a.value.bad.length) issues.push(r+" "+JSON.stringify(a.value));
  }
  out[v]=issues.length?issues:"clean";
}
console.log(JSON.stringify(out,null,1));

