(()=>{
 const w=document.getElementById('frame').contentWindow,d=document.getElementById('frame').contentDocument;
 const el=d.querySelector('.users__table'); if(!el) return 'missing table';
 const R=el.getBoundingClientRect();
 let n=el,chain=[];
 while(n&&n!==d.documentElement){const cs=w.getComputedStyle(n);
   chain.push({tag:n.tagName,cls:String(n.className).slice(0,44),ovx:cs.overflowX,
     sw:n.scrollWidth,cw:n.clientWidth,scrollable:n.scrollWidth>n.clientWidth+1,
     w:Math.round(n.getBoundingClientRect().width)});
   n=n.parentElement}
 return {vw:w.innerWidth,docScrollW:d.documentElement.scrollWidth,docClientW:d.documentElement.clientWidth,
   table:{left:Math.round(R.left),right:Math.round(R.right),w:Math.round(R.width)},
   chain:chain.slice(0,7)}})()
